1	import { Injectable } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	
4	@Injectable()
5	export class PlataformaService {
6	  constructor(private supabase: SupabaseService) {}
7	
8	  async metricas() {
9	    const [
10	      { data: empresas },
11	      { data: pedidos },
12	      { data: comissoes },
13	    ] = await Promise.all([
14	      this.supabase.client.from('restaurants').select('id, name, comissao_pct'),
15	      this.supabase.client.from('orders').select('id, total, status, restaurant_id'),
16	      this.supabase.client.from('plataforma_comissoes').select('comissao_valor, empresa_id, criado_em'),
17	    ]);
18	
19	    const entregues = (pedidos ?? []).filter((p) => p.status === 'delivered');
20	    const cancelados = (pedidos ?? []).filter((p) => p.status === 'canceled');
21	    const faturamentoTotal = entregues.reduce((acc, p) => acc + (p.total ?? 0), 0);
22	    const comissaoTotal = (comissoes ?? []).reduce((acc, c) => acc + (c.comissao_valor ?? 0), 0);
23	
24	    // Faturamento por empresa (top 5)
25	    const porEmpresa: Record<number, { nome: string; faturamento: number; comissao: number }> = {};
26	    for (const e of empresas ?? []) {
27	      porEmpresa[e.id] = { nome: e.name, faturamento: 0, comissao: 0 };
28	    }
29	    for (const p of entregues) {
30	      if (porEmpresa[p.restaurant_id]) {
31	        porEmpresa[p.restaurant_id].faturamento += p.total ?? 0;
32	      }
33	    }
34	    for (const c of comissoes ?? []) {
35	      if (porEmpresa[c.empresa_id]) {
36	        porEmpresa[c.empresa_id].comissao += c.comissao_valor ?? 0;
37	      }
38	    }
39	
40	    const topEmpresas = Object.entries(porEmpresa)
41	      .map(([id, v]) => ({ empresa_id: parseInt(id), ...v }))
42	      .sort((a, b) => b.faturamento - a.faturamento)
43	      .slice(0, 5);
44	
45	    return {
46	      resumo: {
47	        total_empresas: empresas?.length ?? 0,
48	        total_pedidos: pedidos?.length ?? 0,
49	        pedidos_entregues: entregues.length,
50	        pedidos_cancelados: cancelados.length,
51	        faturamento_total: parseFloat(faturamentoTotal.toFixed(2)),
52	        comissao_total: parseFloat(comissaoTotal.toFixed(2)),
53	        ticket_medio: entregues.length > 0 ? parseFloat((faturamentoTotal / entregues.length).toFixed(2)) : 0,
54	      },
55	      top_empresas: topEmpresas,
56	    };
57	  }
58	
59	  async comissoes(filtros: {
60	    empresa_id?: number;
61	    data_inicio?: string;
62	    data_fim?: string;
63	    limite?: number;
64	  }) {
65	    let query = this.supabase.client
66	      .from('plataforma_comissoes')
67	      .select('id, empresa_id, pedido_id, valor_venda, comissao_pct, comissao_valor, criado_em')
68	      .order('criado_em', { ascending: false })
69	      .limit(filtros.limite ?? 100);
70	
71	    if (filtros.empresa_id) query = query.eq('empresa_id', filtros.empresa_id);
72	    if (filtros.data_inicio) query = query.gte('criado_em', filtros.data_inicio);
73	    if (filtros.data_fim) query = query.lte('criado_em', filtros.data_fim + 'T23:59:59');
74	
75	    const { data, error } = await query;
76	    if (error) throw error;
77	
78	    const total = (data ?? []).reduce((acc, c) => acc + (c.comissao_valor ?? 0), 0);
79	
80	    return {
81	      comissoes: data,
82	      total_registros: data?.length ?? 0,
83	      total_comissao: parseFloat(total.toFixed(2)),
84	    };
85	  }
86	
87	  async getConfig() {
88	    const { data } = await this.supabase.client
89	      .from('platform_settings')
90	      .select('config')
91	      .eq('id', 1)
92	      .maybeSingle();
93	
94	    const cfg = (data?.config ?? {}) as Record<string, any>;
